const item = $input.first().json;
const body = item.body || {};
const headers = item.headers || {};

const receivedSignature = headers['x-kredo-signature'] || headers['X-KREDO-Signature'] || '';
const expectedSignature = 'sha256=' + (item.computedSignature || '');

if (!receivedSignature || receivedSignature !== expectedSignature) {
  throw new Error('Signature HMAC invalide (X-KREDO-Signature) — requête rejetée');
}

const required = ['runId', 'workflowId', 'entityType', 'entityId', 'workspaceId', 'userId', 'input', 'callbackUrl'];
for (const field of required) {
  if (!body[field]) throw new Error(`Champ requis manquant dans le payload : ${field}`);
}

const brief = body.input;
if (!brief || brief.reportType !== 'client_summary') {
  throw new Error('input.reportType doit valoir "client_summary" pour ce workflow');
}
if (body.entityType !== 'company') {
  throw new Error('report-account-summary requiert entityType="company"');
}

return [{
  json: {
    runId: body.runId,
    workflowId: body.workflowId,
    workspaceId: body.workspaceId,
    userId: body.userId,
    companyId: body.entityId,
    brief: brief,
    callbackUrl: body.callbackUrl,
  }
}];

const briefData = $('Validate Brief').item.json;
const facts = $input.first().json;
const brief = briefData.brief;

const SYSTEM_PROMPT = `Tu rédiges la section "Analyse & conviction" d'une fiche de synthèse compte
pour Kredo Digital (ESN premium : Data/IA, Cloud, Product Management, Cybersécurité).

RÈGLES ABSOLUES :
1. Tu reçois un dictionnaire de FAITS déjà calculés (JSON ci-dessous). Ce sont les
   SEULES données chiffrées que tu as le droit de citer. Tu ne dois JAMAIS inventer,
   arrondir différemment, ou déduire un chiffre qui n'apparaît pas explicitement
   dans les FAITS.
2. Les notes de conviction et d'investissement (facts.scores) sont déjà calculées —
   tu dois les EXPLIQUER, jamais les recalculer ni proposer une note différente.
3. Si une donnée est absente (null) ou couverte par un caveat, dis-le explicitement
   plutôt que de combler le vide par une supposition.
4. Style : direct, factuel, sans superlatifs creux ("leader", "unique").

FORMAT DE SORTIE :
Réponds UNIQUEMENT en JSON valide, sans backticks, structure obligatoire :
{
  "analysis": "3 à 5 lignes de synthèse sur l'activité et la santé du compte",
  "recommendedApproach": {
    "practice": "practice Kredo la plus pertinente ou null si aucun signal suffisant",
    "offer": "offre/thème à mettre en avant ou null",
    "argument": "1-2 phrases expliquant pourquoi cette approche est pertinente compte tenu des FAITS"
  },
  "nextBestAction": "une action concrète et unique à mener sur ce compte",
  "source_refs": ["clé de fact utilisée, ex: potential.openPipeWeighted"],
  "warnings": ["avertissement si la donnée est insuffisante pour une section"]
}`;

const detailLevel = (brief.detailLevel) || 'standard';
const audience = (brief.audience) || 'self';
const instructions = brief.additionalInstructions || '(aucune)';

const userPrompt = `NIVEAU DE DÉTAIL DEMANDÉ : ${detailLevel}
DESTINATAIRE DU RAPPORT : ${audience}
INSTRUCTIONS COMPLÉMENTAIRES : ${instructions}

FAITS (source unique de vérité — JSON) :
${JSON.stringify(facts, null, 2)}`;

return [{
  json: {
    ...briefData,
    facts,
    systemPrompt: SYSTEM_PROMPT,
    userPrompt,
  }
}];

