const response = $input.first().json;
const upstream = $('Assemble Prompt').item.json;
const textBlock = (response.content || []).find(b => b.type === 'text');
const content = textBlock && textBlock.text;

if (!content) {
  throw new Error('Le LLM a renvoyé un contenu vide');
}

let parsed;
try {
  const clean = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  throw new Error('Réponse LLM non-JSON : ' + content.slice(0, 200));
}

if (!parsed.analysis || parsed.analysis.length < 20) {
  throw new Error('analysis vide ou trop courte');
}
if (!parsed.recommendedApproach || !parsed.nextBestAction) {
  throw new Error('recommendedApproach ou nextBestAction manquant');
}

return [{
  json: {
    ...upstream,
    narrative: parsed,
    llmUsage: {
      inputTokens: (response.usage && response.usage.input_tokens) || null,
      outputTokens: (response.usage && response.usage.output_tokens) || null,
      model: response.model || 'claude-sonnet-5',
    },
  }
}];

// Contrôle "chiffres non autorisés" : tout nombre à 2+ chiffres cité dans la
// narration doit apparaître quelque part dans les FAITS sérialisés. Heuristique
// volontairement simple (pas de NLP) — un faux positif reste possible sur des
// nombres fortuits (ex. "3 axes"), donc ce n'est qu'un flag, pas un blocage dur.
const data = $input.first().json;
const narrative = data.narrative;
const factsStr = JSON.stringify(data.facts);
const qaFlags = [];

const narrativeText = [
  narrative.analysis,
  narrative.recommendedApproach && narrative.recommendedApproach.argument,
  narrative.nextBestAction,
].filter(Boolean).join(' ');

const numbers = narrativeText.match(/\d{2,}/g) || [];
const unauthorized = numbers.filter((n) => !factsStr.includes(n));
if (unauthorized.length > 0) {
  qaFlags.push({ check: 'no_unauthorized_numbers', passed: false, detail: `Nombres absents des FAITS : ${unauthorized.join(', ')}` });
} else {
  qaFlags.push({ check: 'no_unauthorized_numbers', passed: true });
}

const analysisWordCount = (narrative.analysis || '').split(/\s+/).filter(Boolean).length;
if (analysisWordCount < 15 || analysisWordCount > 120) {
  qaFlags.push({ check: 'analysis_length', passed: false, detail: `${analysisWordCount} mots (attendu 15-120, cible 3-5 lignes)` });
} else {
  qaFlags.push({ check: 'analysis_length', passed: true, detail: `${analysisWordCount} mots` });
}

if (data.facts.caveats && data.facts.caveats.length > 0) {
  qaFlags.push({ check: 'data_coverage_caveats', passed: true, detail: data.facts.caveats.join(' | ') });
}

return [{ json: { ...data, qaFlags } }];

const data = $input.first().json;

const contentJson = {
  facts: data.facts,
  narrative: data.narrative,
  sourceRefs: (data.narrative.source_refs || []).map((key) => ({ entityType: 'fact', label: key })),
  qaFlags: data.qaFlags || [],
};

const callbackBody = {
  runId: data.runId,
  phase: 1,
  resultType: 'client_summary',
  status: 'succeeded',
  contentJson,
  title: `Synthèse — ${(data.facts.identity && data.facts.identity.name) || 'Compte'}`,
  modelProvider: 'anthropic',
  modelUsed: (data.llmUsage && data.llmUsage.model) || 'claude-sonnet-5',
  tokensInput: (data.llmUsage && data.llmUsage.inputTokens) || null,
  tokensOutput: (data.llmUsage && data.llmUsage.outputTokens) || null,
  contextSnapshot: data.facts,
  sourceRefs: contentJson.sourceRefs,
  qaFlags: data.qaFlags || [],
};

return [{
  json: {
    callbackUrl: data.callbackUrl,
    rawBody: JSON.stringify(callbackBody),
  }
}];

const errItem = $input.first().json;
let runId = null;
let callbackUrl = null;

try {
  const vb = $('Validate Brief').item.json;
  runId = vb.runId || null;
  callbackUrl = vb.callbackUrl || null;
} catch (e) {
  // Validate Brief n'a produit aucune sortie exploitable — notification impossible.
}

let errorMessage = 'Erreur inconnue dans le workflow report-account-summary';
if (errItem && errItem.error) {
  errorMessage = typeof errItem.error === 'string' ? errItem.error : (errItem.error.message || JSON.stringify(errItem.error));
} else if (errItem && errItem.message) {
  errorMessage = errItem.message;
}

const callbackBody = {
  runId,
  phase: 1,
  resultType: 'client_summary',
  status: 'failed',
  contentJson: {},
  errorMessage,
};

return [{ json: { callbackUrl, rawBody: JSON.stringify(callbackBody) } }];
